function getSignals(){const source=state.mode==='real'&&state.catalogMode==='overview'&&state.real?.activity_catalog?state.real.activity_catalog:state.signals;return source.filter(s=>s.f1>state.center-state.bandwidth/2&&s.f0<state.center+state.bandwidth/2)}
function actualTime(s,k){return s[k]*state.duration/100}
function initialBoxes(s){const boxes=[];for(let i=0;i<s.initial;i++){const parts=s.type==='wifi'?3:1;const col=i%parts,row=Math.floor(i/parts),rows=Math.ceil(s.initial/parts);boxes.push({...s,f0:s.f0+(s.f1-s.f0)*(col/parts+.025),f1:s.f0+(s.f1-s.f0)*((col+1)/parts-.025),t0:s.t0+(s.t1-s.t0)*(row/rows+.04),t1:s.t0+(s.t1-s.t0)*((row+1)/rows-.04),boxLabel:'g'+String(i+1).padStart(2,'0'),initialBox:true})}return boxes}
function chartBoxes(){if(state.mode==='real'&&state.real){if(state.real.segmentation_level==='coarse_activity'){
 if(state.stage===0)return state.realStages[0]||[];
 if(state.stage===1)return (state.realStages[1]||[]).filter(s=>!state.fineWindow||s.id.startsWith(state.fineWindow+'_'));
 const coarse=state.signals.filter(s=>s.status!=='verified'),frames=state.signals.filter(s=>s.status==='verified');
 const selected=getSignals().find(s=>s.id===state.selected&&s.status==='verified')||frames.find(s=>s.id===state.selected);
 return [...coarse,...($('#show-frame-layer').checked?frames:selected?(selected.members||[selected]):[])];
 }if(state.stage===2&&state.catalogMode==='overview'&&state.real.activity_catalog)return getSignals().filter(s=>s.status==='verified'||s.id===state.selected).flatMap(s=>(s.members||[s]).slice(0,s.status==='verified'?10000:40).map(m=>({...m,id:s.status==='verified'?m.id:s.id,catalog_id:s.id,name:m.name,type:s.type,status:s.status})));return state.stage===2?state.signals:state.realStages[state.stage]||state.signals;}return getSignals().flatMap(s=>state.stage===0?initialBoxes(s):state.stage===1?[...initialBoxes(s),{...s,reviewBox:true}]:[s])}
function visibleRange(){const width=state.bandwidth/state.zoom;return [state.center+state.pan-width/2,state.center+state.pan+width/2]}
function visibleTimeRange(){const span=100/state.timeZoom;return [50+state.timePan-span/2,50+state.timePan+span/2]}
function clampTimePan(){const half=50-50/state.timeZoom;state.timePan=Math.max(-half,Math.min(half,state.timePan))}
function timeAtY(ratio){const [early,late]=visibleTimeRange();return late-ratio*(late-early)}
function timeToY(t){const [early,late]=visibleTimeRange();return (late-t)/(late-early)}
function prepareCanvas(c){const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d)}const ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);return [ctx,r.width,r.height]}
function draw(){drawPSD();drawWaterfall();renderCatalogSummary();requestDetail()}
function drawPSD(){const [ctx,w,h]=prepareCanvas($('#psd'));if(!w)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#0d1711';ctx.fillRect(0,0,w,h);const l=42,r=w-15,[lo,hi]=visibleRange();ctx.strokeStyle='#25382a';ctx.lineWidth=.6;for(let i=0;i<4;i++){const y=14+i*16;ctx.beginPath();ctx.moveTo(l,y);ctx.lineTo(r,y);ctx.stroke()}let values=[];for(let i=0;i<Math.ceil(r-l);i++){const f=lo+i/(r-l)*(hi-lo);let v=state.mode==='real'&&!state.real?0:7+2*Math.sin(f*8)+Math.sin(f*31);if(state.mode==='real'&&state.real?.visual?.psd_db){const vis=state.real.visual,ix=Math.floor((f-vis.low_mhz)/(vis.high_mhz-vis.low_mhz)*vis.psd_db.length);if(ix>=0&&ix<vis.psd_db.length)v=(vis.psd_db[ix]-vis.min_db)/(vis.max_db-vis.min_db)*48}else{for(const s of getSignals()){if(f>s.f0&&f<s.f1)v+=s.type==='wifi'?28+4*Math.sin(f*19):s.type==='ble'?35:18+4*Math.sin(f*7)}}values.push(Math.max(3,Math.min(57,v)))}ctx.beginPath();values.forEach((v,i)=>i?ctx.lineTo(l+i,h-8-v):ctx.moveTo(l+i,h-8-v));ctx.strokeStyle='#a6ce93';ctx.lineWidth=1;ctx.stroke();ctx.lineTo(l+values.length,h);ctx.lineTo(l,h);ctx.closePath();const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#a2c98b27');g.addColorStop(1,'#a2c98b00');ctx.fillStyle=g;ctx.fill()}
function palette(v){const stops=[[9,24,19],[17,48,37],[34,88,61],[79,137,78],[160,180,101],[228,210,135]];const z=Math.max(0,Math.min(.999,v))*(stops.length-1),i=Math.floor(z),a=z-i;return stops[i].map((v,k)=>Math.round(v+(stops[i+1][k]-v)*a))}
function drawWaterfall(){const [ctx,w,h]=prepareCanvas($('#waterfall'));if(!w)return;const pad={l:42,r:15,t:10,b:30},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b,[lo,hi]=visibleRange();ctx.fillStyle='#0c1510';ctx.fillRect(0,0,w,h);const nx=Math.max(1,Math.floor(cw/2)),ny=Math.max(1,Math.floor(ch/2));const off=document.createElement('canvas');off.width=nx;off.height=ny;const oc=off.getContext('2d'),img=oc.createImageData(nx,ny);const sigs=getSignals();const real=state.mode==='real'&&state.real?.visual;
 for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const f=lo+x/nx*(hi-lo),t=timeAtY((y+.5)/ny);let val=state.mode==='real'&&!state.real?0:.08+.035*(Math.sin(x*12.91+y*78.23)*43758.5453%1+1);if(real){const detail=state.detail,vis=detail&&t>=detail.low_time_percent&&t<=detail.high_time_percent?detail:state.real.visual;const [early,late]=visibleTimeRange();const tA=late-y/ny*(late-early),tB=late-(y+1)/ny*(late-early);val=sampleVisual(vis,f,lo+(x+1)/nx*(hi-lo),tB,tA)}else for(const s of sigs){if(t>=s.t0&&t<=s.t1&&f>=s.f0&&f<=s.f1){if(s.id==='s5'){const ridge=s.f0+(s.f1-s.f0)*(t-s.t0)/(s.t1-s.t0);if(Math.abs(f-ridge)<.5)val+=.7}else{const edge=Math.min((f-s.f0)/(s.f1-s.f0),(s.f1-f)/(s.f1-s.f0));val+=((s.type==='wifi'?.48:.66)+.12*Math.sin(x*3+y*13))*Math.min(1,edge*15)}}}const col=palette(val),at=(y*nx+x)*4;img.data[at]=col[0];img.data[at+1]=col[1];img.data[at+2]=col[2];img.data[at+3]=255}oc.putImageData(img,0,0);ctx.imageSmoothingEnabled=false;ctx.drawImage(off,pad.l,pad.t,cw,ch);ctx.lineWidth=.5;ctx.strokeStyle='#81b99416';ctx.font='9px "IBM Plex Mono",Consolas,monospace';ctx.fillStyle='#72937c';for(let i=0;i<=5;i++){const x=pad.l+cw*i/5;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,h-pad.b);ctx.stroke();ctx.textAlign='center';ctx.fillText((lo+(hi-lo)*i/5).toFixed(state.zoom>3?2:0),x,h-12)}ctx.textAlign='right';for(let i=0;i<=5;i++){const y=pad.t+ch*i/5;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillText((state.duration*timeAtY(i/5)/100).toFixed(state.timeZoom>3?2:1),pad.l-7,y+3)}ctx.textAlign='right';ctx.fillText('MHz',w-2,h-12);
 if($('#show-boxes').checked)for(const s of chartBoxes()){const x0=pad.l+(s.f0-lo)/(hi-lo)*cw,x1=pad.l+(s.f1-lo)/(hi-lo)*cw,y0=pad.t+timeToY(s.t1)*ch,y1=pad.t+timeToY(s.t0)*ch;if(x1<pad.l||x0>w-pad.r||y1<pad.t||y0>h-pad.b)continue;ctx.save();ctx.beginPath();ctx.rect(pad.l,pad.t,cw,ch);ctx.clip();const selected=s.id===state.selected,col=s.initialBox?'#a0ba9b':colors[s.type]||colors.unknown;ctx.strokeStyle=col;ctx.lineWidth=selected&&!s.initialBox?1.8:1;ctx.setLineDash(s.segmentation_level==='coarse_activity'?[5,3]:s.initialBox?[3,3]:s.reviewBox?[6,3]:[]);ctx.fillStyle=col+(selected&&!s.initialBox?'20':'09');if(y1-y0<1.5){ctx.beginPath();ctx.moveTo(x0,(y0+y1)/2);ctx.lineTo(x1,(y0+y1)/2);ctx.stroke()}else{ctx.fillRect(x0,y0,x1-x0,y1-y0);ctx.strokeRect(x0,y0,x1-x0,y1-y0)}ctx.setLineDash([]);if($('#show-labels').checked&&!s.initialBox&&x1-x0>22&&(state.mode==='demo'||selected)){let label=s.reviewBox?'复查范围':s.name.split(' · ')[0];const tw=ctx.measureText(label).width;ctx.fillStyle=col;ctx.fillRect(x0,Math.max(pad.t,y0-15),tw+10,15);ctx.fillStyle='#152419';ctx.textAlign='left';ctx.fillText(label,x0+5,Math.max(pad.t+10,y0-4))}ctx.restore()}
 $('#empty-chart').textContent=state.mode==='real'?'等待真实任务的时频数据':'当前频段内没有此演示场景的数据';$('#empty-chart').hidden=sigs.length>0||!!real}
function selectSignal(id,focus=false){state.selected=id;renderEvidence();renderTable();draw();if(focus&&innerWidth<980)$('.evidence-panel').classList.add('mobile-open')}
function renderEvidence(){const s=[...getSignals(),...state.signals,...state.realStages.flat()].find(s=>s.id===state.selected)||getSignals()[0];if(!s){$('#evidence-content').innerHTML='<div class="evidence-body"><h3>等待观测结果</h3><p class="evidence-subtitle">选择任务并开始分析，结果将在这里显示。</p></div>';return}state.selected=s.id;const demo=state.mode==='demo',tag=demo?(s.status==='verified'?'演示校验':'演示候选'):(s.status==='verified'?'完整性校验':s.evidence_state||'尚未验证');$('#evidence-level').textContent=tag;$('#evidence-level').style.color=colors[s.type];$('#evidence-content').innerHTML=`<div class="evidence-body"><div class="evidence-kicker"><span>${escapeHTML(s.id.toUpperCase())}</span><span>${demo?'DEMO EVIDENCE':'MEASURED EVIDENCE'}</span></div><h3 class="evidence-title" style="color:${colors[s.type]}">${escapeHTML(s.name.split(' · ')[0])}</h3><div class="evidence-subtitle">${escapeHTML(s.description||'当前仅检测到时频活动，尚无足够协议证据。')}</div><div class="evidence-summary"><div><span>频率范围</span><strong>${s.f0.toFixed(2)}–${s.f1.toFixed(2)} MHz</strong></div><div><span>估计带宽</span><strong>${(s.f1-s.f0).toFixed(2)} MHz${s.bandwidth_is_decoder_passband?' · 验证通带':''}</strong></div><div><span>${s.members?'活动索引跨度（含间隔）':s.frame_time_estimated?'单帧位置（同步估计）':'检测区域时间'}</span><strong>${actualTime(s,'t0').toFixed(s.frame_time_estimated&&!s.members?5:3)}–${actualTime(s,'t1').toFixed(s.frame_time_estimated&&!s.members?5:3)} ms${s.frame_time_estimated&&!s.members?'<br>主体 '+s.frame_duration_us.toFixed(2)+' μs · 未标定':''}</strong></div><div><span>证据状态</span><strong>${s.status==='verified'?(demo?'演示 CRC 通过':'校验帧证据'):escapeHTML(s.evidence_state||'协议尚未确认')}</strong></div></div><div class="mini-heading">识别与复查依据</div>${(s.steps||['能量检测与时频区域','通用特征或协议证据不足','保留 unknown 并等待进一步验证']).map((x,i)=>`<div class="evidence-item"><span>${String(i+1).padStart(2,'0')}</span><span>${escapeHTML(x)}</span></div>`).join('')}<div class="boundary-change"><h3>⟳ 分割与识别的反馈</h3><p>${escapeHTML(s.change||'保留原始检测区域；只有新增证据才支持边界修正，不直接将整条谱迹标为已确认协议。')}</p></div><button class="evidence-jump" id="focus-region">定位到此区域 ↗</button>${innerWidth<980?'<button class="evidence-jump" id="close-evidence">关闭面板 ×</button>':''}</div><div class="evidence-disclaimer">${demo?'此处为交互演示证据，不是实际解码结果。':'区域重叠是候选关联，不代表设备身份，也不等于整片区域均属于同一协议。'}</div>`;$('#focus-region').onclick=()=>{const bw=s.f1-s.f0;if(state.mode==='real'){state.timeZoom=Math.max(1,Math.min(1000,100/Math.max((s.t1-s.t0)*3,.1)));state.timePan=(s.t0+s.t1)/2-50;clampTimePan()}state.zoom=Math.min(12,state.bandwidth/Math.max(bw*2,2));state.pan=(s.f0+s.f1)/2-state.center;clampPan();draw();$('.evidence-panel').classList.remove('mobile-open')};if($('#close-evidence'))$('#close-evidence').onclick=()=>$('.evidence-panel').classList.remove('mobile-open')}
function renderTable(){let sigs=getSignals().slice().sort((a,b)=>Number(b.status==='verified')-Number(a.status==='verified'));if(state.filter==='verified')sigs=sigs.filter(s=>s.status==='verified');if(state.filter==='unknown')sigs=sigs.filter(s=>s.status!=='verified');$('#signal-count').textContent=getSignals().length;$('#signal-rows').innerHTML=sigs.map(s=>`<tr data-signal="${escapeHTML(s.id)}" class="${s.id===state.selected?'selected':''}" tabindex="0"><td><span class="signal-name" style="--signal-color:${colors[s.type]}"><i></i>${escapeHTML(s.name)}</span><span class="signal-id">${escapeHTML(s.id.toUpperCase())}</span></td><td style="font-family:var(--mono)">${((s.f0+s.f1)/2).toFixed(2)} MHz</td><td>${escapeHTML(s.feature||'待分析')}</td><td><span class="tag ${s.status==='verified'?'':'pending'}">${state.mode==='demo'?'示例 · ':''}${s.status==='verified'?'校验依据':escapeHTML(s.evidence_state||'尚未验证')}</span></td><td>${escapeHTML(s.action||'保留待验证')}</td></tr>`).join('')||'<tr><td colspan="5">当前筛选条件下没有信号。</td></tr>';$$('[data-signal]').forEach(r=>{r.onclick=()=>selectSignal(r.dataset.signal,true);r.onkeydown=e=>{if(e.key==='Enter')r.click()}})}
