function renderTiming(){const spans=state.mode==='real'?(state.real?.timing||[]):[{name:'模型调用',seconds:56.8},{name:'采集与初始化',seconds:13.5},{name:'全带分割',seconds:11.2},{name:'滤波与特征',seconds:6.4},{name:'校验与复查',seconds:4.5}];const max=Math.max(...spans.map(s=>s.seconds),1);$('#timing-bars').innerHTML=spans.map((s,i)=>`<div class="timing-row"><div><span>${escapeHTML(s.name)}</span><strong>${s.seconds.toFixed(2)}s</strong></div><div class="timing-track"><i style="width:${s.seconds/max*100}%;background:${i===0?'#b2dc9a':i===2?'#74a589':'#66856d'}"></i></div></div>`).join('');$('.timing-total>strong').innerHTML=`${(state.mode==='real'?state.real?.elapsed_s||0:104).toFixed(1)}<small>s</small>`;$('.timing-panel .subtle').textContent=state.mode==='real'?'实测记录':'演示示意'}
function render(){renderCatalogSummary();renderMetrics();renderTable();renderEvidence();renderTiming();if(state.mode==='real'&&state.real){$('.table-note').textContent=state.real.warning||'区域重叠为候选关联，不代表设备身份。完整原始事件保存在导出报告中。'}else{$('.table-note').textContent='演示数据：波形特征不等于协议确认，未知活动始终保留。点击任意行查看时频区域。'}setStage(state.stage)}
