async function runTask(){if(state.running){if(state.mode==='real'&&state.task){await api(`/edge/tasks/${state.task}/cancel`,{method:'POST'});toast('已请求取消，等待释放设备')}else{clearInterval(runTimer);state.running=false;$('#run-task').innerHTML='▶ 开始演示';$('#result-status').textContent='演示已停止'}return}if(!validate()||!$('#prompt').value.trim()){toast('请填写任务描述和有效参数');return}stopPlayer();state.zoom=1;state.pan=0;state.timeZoom=1;state.timePan=0;if(state.mode==='real'){await startReal();return}state.signals=demoSignals(state.preset);state.running=true;setStage(0);render();$('#run-task').textContent='■ 停止演示';const labels=['演示：全带能量检测','演示：特征与协议证据','演示：局部边界复查','演示：保留确认与未知'];let step=0;$('#result-status').textContent=labels[0];runTimer=setInterval(()=>{step++;if(step>=4){clearInterval(runTimer);finishDemo();return}$('#result-status').textContent=labels[step];setStage(Math.min(step,2))},1100)}
