async function switchMode(mode){if(state.running){toast('请先结束当前任务');return}if(mode==='real'&&!state.connected){toast('真实模式请打开连接 Jetson 的本机入口，云端原型只提供演示');return}state.mode=mode;$('#signal-filter [data-filter=verified]').textContent=mode==='real'?'已校验':'示例确认';$('.metric:nth-child(3)>span').innerHTML=mode==='real'?'已验证协议 <i>◇</i>':'示例协议证据 <i>◇</i>';$('.legend').innerHTML=mode==='real'?'<span><i class="wifi-color"></i>有效 Wi-Fi 帧</span><span><i class="ble-color"></i>有效 BLE 帧</span><span><i class="unknown-color"></i>未知 / 候选</span>':'<span><i class="wifi-color"></i>Wi-Fi 示例</span><span><i class="ble-color"></i>BLE 示例</span><span><i class="unknown-color"></i>未知 / 待验证</span><span><i class="initial-color"></i>初始候选</span>';state.real=null;state.realStages=[];state.signals=mode==='demo'?demoSignals(state.preset):[];state.task=null;$('.device-status').innerHTML=`<span class="status-dot" style="background:${mode==='real'?'var(--green)':'var(--amber)'}"></span>${mode==='real'?'Jetson API 已连接':'交互演示模式'}<span class="pill">${mode==='real'?'LIVE':'DEMO'}</span>`;$('.demo-badge').innerHTML=`<i></i>${mode==='real'?'真实设备模式 · 接收任务':'交互原型 · 示例数据'}`;$('.sidebar-bottom p').innerHTML=mode==='real'?'任务通过本机隧道提交给 Jetson。<br>采集与分析结果来自真实任务。':'未连接设备，不会启动射频采集。<br>示例标签不代表现场识别结果。';$('.page-footer>span:last-child').textContent=mode==='real'?'真实数据入口 · 独立可视化层 · Harness 保持无界面':'交互设计原型 · 示例数据 · 不执行射频操作';$('#run-task').textContent=mode==='real'?'▶ 启动真实任务':'▶ 开始演示';$('#export-report').textContent=mode==='real'?'↓ 导出任务报告':'↓ 导出演示报告';$('#result-status').textContent=mode==='real'?'等待提交真实任务':'演示结果已就绪';render();if(mode==='real')await refreshRealHistory()}
