const waterfall=$('#waterfall');let lastHitAmbiguous=false,detailTimer,detailGeneration=0;
function sampleVisual(vis,f0,f1,t0,t1){
 const early=vis.low_time_percent??0,late=vis.high_time_percent??100;
 const x0=Math.max(0,Math.floor((f0-vis.low_mhz)/(vis.high_mhz-vis.low_mhz)*vis.columns)),x1=Math.min(vis.columns-1,Math.ceil((f1-vis.low_mhz)/(vis.high_mhz-vis.low_mhz)*vis.columns)-1);
 const y0=Math.max(0,Math.floor((t0-early)/(late-early)*vis.rows)),y1=Math.min(vis.rows-1,Math.ceil((t1-early)/(late-early)*vis.rows)-1);let peak=-Infinity;
 for(let y=y0;y<=Math.max(y0,y1)&&y<vis.rows;y++)for(let x=x0;x<=Math.max(x0,x1)&&x<vis.columns;x++)if(vis.db[y])peak=Math.max(peak,vis.db[y][x]);
 return Number.isFinite(peak)?(peak-vis.min_db)/(vis.max_db-vis.min_db):0;
}
function requestDetail(){
 if(state.mode!=='real'||!state.real||state.timeZoom<5)return;
 const [early,late]=visibleTimeRange(),start=early*state.duration/100,end=late*state.duration/100;
 const key=state.task+':'+start.toFixed(5)+':'+end.toFixed(5);if(state.detailKey===key)return;
 state.detailKey=key;const generation=++detailGeneration,task=state.task;clearTimeout(detailTimer);
 detailTimer=setTimeout(async()=>{try{const detail=await api('/edge/tasks/'+task+'/waterfall-window?start_ms='+start+'&end_ms='+end);if(generation!==detailGeneration||task!==state.task||state.mode!=='real')return;state.detail=detail;draw()}catch(e){if(generation===detailGeneration)$('#catalog-summary').textContent+=' · 局部STFT暂不可用：'+e.message}},220);
}
function hitSignal(e){
 const r=waterfall.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,[lo,hi]=visibleRange();lastHitAmbiguous=false;
 if(x<42||x>r.width-15||y<10||y>r.height-30)return;
 const pool=state.mode==='real'?chartBoxes():getSignals(),hits=[];
 for(const s of pool){const x0=42+(s.f0-lo)/(hi-lo)*(r.width-57),x1=42+(s.f1-lo)/(hi-lo)*(r.width-57),y0=10+timeToY(s.t1)*(r.height-40),y1=10+timeToY(s.t0)*(r.height-40),thin=y1-y0<1.5;
  if(x<x0||x>x1)continue;
  const distance=thin?Math.abs(y-(y0+y1)/2):Math.max(y0-y,y-y1,0);
  if(distance<=(thin?1:0))hits.push({s,distance,thin});
 }
 hits.sort((a,b)=>a.distance-b.distance||(a.s.f1-a.s.f0)*(a.s.t1-a.s.t0)-(b.s.f1-b.s.f0)*(b.s.t1-b.s.t0));
 if(hits[0]?.thin&&new Set(hits.filter(h=>h.thin).map(h=>h.s.id)).size>1)lastHitAmbiguous=true;
 return hits[0]?.s;
}
// Plot: zoom both axes. Axis margins isolate frequency/time; Shift isolates time.
function zoomChart(e){
 const r=waterfall.getBoundingClientRect(),isPSD=e.currentTarget.id==='psd',x=e.clientX-r.left,y=e.clientY-r.top;
 const delta=e.deltaY||e.deltaX;if(!delta)return;e.preventDefault();e.stopPropagation();
 const factor=Math.exp(-Math.max(-240,Math.min(240,delta*(e.deltaMode===1?16:e.deltaMode===2?300:1)))*.002);
 const timeOnly=!isPSD&&(e.shiftKey||x<42),frequencyOnly=isPSD||(!timeOnly&&y>r.height-30);
 if(!timeOnly){const ratio=Math.max(0,Math.min(1,(x-42)/(r.width-57))),[lo,hi]=visibleRange(),anchor=lo+ratio*(hi-lo);state.zoom=Math.max(1,Math.min(100,state.zoom*factor));state.pan=anchor-state.center+(state.bandwidth/state.zoom)*(.5-ratio);clampPan()}
 if(!frequencyOnly){const ratio=Math.max(0,Math.min(1,(y-10)/(r.height-40))),anchor=timeAtY(ratio);state.timeZoom=Math.max(1,Math.min(1000,state.timeZoom*factor));state.timePan=anchor-50-(.5-ratio)*100/state.timeZoom;clampTimePan()}
 $('#chart-tooltip').style.display='none';draw();
}
waterfall.addEventListener('wheel',zoomChart,{passive:false});$('#psd').addEventListener('wheel',zoomChart,{passive:false});
waterfall.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,pan:state.pan,timePan:state.timePan,moved:false};waterfall.setPointerCapture(e.pointerId)});waterfall.addEventListener('pointermove',e=>{const r=waterfall.getBoundingClientRect();if(drag){const delta=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(delta,dy)>4)drag.moved=true;state.timePan=drag.timePan+dy/(r.height-40)*100/state.timeZoom;clampTimePan();state.pan=drag.pan-delta/(r.width-57)*(state.bandwidth/state.zoom);clampPan();draw();return}hovered=hitSignal(e);const tip=$('#chart-tooltip');if(hovered){tip.textContent=hovered.name+' · '+(state.mode==='demo'?'演示数据':hovered.status==='verified'?'有效帧证据':'协议未知');tip.style.display='block';tip.style.left=Math.min(e.clientX-r.left+12,r.width-190)+'px';tip.style.top=Math.max(10,e.clientY-r.top-34)+'px'}else tip.style.display='none'});waterfall.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const s=hitSignal(e);if(s){if(lastHitAmbiguous){state.timeZoom=Math.min(1000,Math.max(state.timeZoom*5,200));state.timePan=(s.t0+s.t1)/2-50;clampTimePan();draw();toast('该像素包含多个短帧，已放大时间轴；请再次选择具体帧')}else selectSignal(s.id,true)}}drag=null});waterfall.addEventListener('pointerleave',()=>$('#chart-tooltip').style.display='none');waterfall.addEventListener('pointercancel',()=>drag=null);new ResizeObserver(()=>requestAnimationFrame(draw)).observe($('.spectrum-shell'));
